// Helper functions
func getHealthColor(status string) string {
	switch status {
	case "healthy":
		return "bg-gradient-to-br from-green-500 to-green-600"
	case "at-risk":
		return "bg-gradient-to-br from-yellow-500 to-yellow-600"
	case "critical":
		return "bg-gradient-to-br from-red-500 to-red-600"
	default:
		return "bg-gradient-to-br from-slate-500 to-slate-600"
	}
}

func getRiskColor(count int) string {
	if count == 0 {
		return "bg-gradient-to-br from-green-500 to-green-600"
	}
	if count <= 2 {
		return "bg-gradient-to-br from-yellow-500 to-yellow-600"
	}
	return "bg-gradient-to-br from-red-500 to-red-600"
}

func getVelocityTrendClass(trend string) string {
	switch trend {
	case "up":
		return "bg-green-500/30 text-green-300"
	case "down":
		return "bg-red-500/30 text-red-300"
	default:
		return "bg-white/20 text-white"
	}
}

func getVelocityTrendIcon(trend string) string {
	switch trend {
	case "up":
		return "📈"
	case "down":
		return "📉"
	default:
		return "➡️"
	}
}

func getLoadColor(points, capacity int) string {
	pct := float64(points) / float64(capacity) * 100
	if pct > 130 {
		return "bg-red-500"
	}
	if pct > 100 {
		return "bg-yellow-500"
	}
	return "bg-green-500"
}

func getRiskBorderColor(severity string) string {
	switch severity {
	case "high":
		return "border-red-400 bg-red-500/20"
	case "medium":
		return "border-yellow-400 bg-yellow-500/20"
	default:
		return "border-blue-400 bg-blue-500/20"
	}
}

func getRiskBadgeColor(severity string) string {
	switch severity {
	case "high":
		return "bg-red-500 text-white"
	case "medium":
		return "bg-yellow-500 text-white"
	default:
		return "bg-blue-500 text-white"
	}
}

func getCompletionColor(pct float64) string {
	if pct >= 90 {
		return "text-green-400"
	}
	if pct >= 70 {
		return "text-blue-400"
	}
	if pct >= 50 {
		return "text-yellow-400"
	}
	return "text-red-400"
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func marshalVelocityData(v models.VelocityData) string {
	data, _ := json.Marshal(v)
	return string(data)
}

func marshalBurndownData(b []models.BurndownPoint) string {
	data, _ := json.Marshal(b)
	return string(data)
}

func smGetAvatarColor(name string) string {
	colors := []string{"bg-blue-500", "bg-green-500", "bg-purple-500", "bg-pink-500", "bg-indigo-500", "bg-teal-500"}
	hash := 0
	for _, c := range name {
		hash += int(c)
	}
	return colors[hash%len(colors)]
}

func smGetInitials(name string) string {
	if name == "" {
		return "?"
	}
	parts := strings.Split(name, " ")
	if len(parts) >= 2 {
		return strings.ToUpper(string(parts[0][0])) + strings.ToUpper(string(parts[len(parts)-1][0]))
	}
	return strings.ToUpper(string(name[0]))
}

